import re
p=r"D:\the-synaptic-sea-2d\design\gdd\command-simulation-layer.md"
lines=open(p,encoding="utf-8").read().split("\n")
def cells(l):
    # strip code spans before counting pipes
    s=re.sub(r"`[^`]*`","X",l)
    return s.count("|")
hdr=None
bad=[]
for i,l in enumerate(lines,1):
    if l.startswith("|"):
        c=cells(l)
        if hdr is None: hdr=c
        elif c!=hdr: bad.append((i,c,hdr,l[:80]))
    else:
        hdr=None
print(len(bad)); 
for b in bad[:20]: print(b)
print("literal \\n:", sum(1 for l in lines if "\\n" in l))
EOF

